---
import Button from "@/components/fundations/buttons/Button.astro";
import Text from "@/components/fundations/typography/Text.astro";
import Kicker from "@/components/fundations/typography/Kicker.astro";

const logos = [
  {
    src: "/brands/1.svg",
  },
  {
    src: "/brands/2.svg",
  },
  {
    src: "/brands/9.svg",
  },
  {
    src: "/brands/4.svg",
  },
  {
    src: "/brands/5.svg",
  },
  {
    src: "/brands/10.svg",
  },
  {
    src: "/brands/6.svg",
  },
  {
    src: "/brands/7.svg",
  },
  {
    src: "/brands/8.svg",
  },
];
---

<section class="bg-white ">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div class="items-center grid grid-cols-1 gap-x-8 gap-y-16 lg:grid-cols-2">
      <div
        class="flex flex-col justify-between w-full h-full max-w-xl p-8 mx-auto shadow lg:mx-0 bg-linear-180 outline outline-base-100 from-base-50 to-base-100 rounded-xl gap-12 lg:gap-24"
      >
        <div>
          <Kicker> Tagline </Kicker>
          <Text
            tag="h2"
            variant="displayMD"
            class="mt-4 font-semibold text-base-900 "
          >
            Come build with us and help revolutionize financing
          </Text>
        </div>
        <div class="flex flex-row items-center mt-8 gap-4">
          <Button variant="accent" size="sm"> Get started </Button>
          <div
            class="font-medium lg:items-center text-s text-base-600 "
          >
            <span class="block"> This is some support text </span>
            <span class="block"> and this is also. </span>
          </div>
        </div>
      </div>
      <div
        class="items-center w-full max-w-xl mx-auto grid grid-cols-2 lg:grid-cols-3 gap-12 lg:mx-0 lg:max-w-none lg:pl-8"
      >
        {
          logos.map((logo) => (
            <img
              class="object-contain object-left w-full max-h-12 "
              src={logo.src}
              alt="#_"
              width="105"
              height="48"
            />
          ))
        }
      </div>
    </div>
  </div>
</section>
